window.QCM = [
  // ---------- 1. Concepts de base ----------
  { ch: 1, q: "Selon ISO/IEC/IEEE 24765:2017, qu'est-ce qui fait partie du logiciel ?", o: ["Uniquement le code source", "Le code source, les procédures, les règles métier, la documentation et les données", "Seulement les programmes exécutables", "Le matériel informatique associé"], a: 1,
    e: "Le logiciel regroupe programmes, procédures, règles, documentation associée et données. La qualité dépasse donc le seul code source." },
  { ch: 1, q: "Quelle est la relation correcte entre erreur, défaut et défaillance ?", o: ["Défaut, puis erreur, puis défaillance", "Défaillance, puis défaut, puis erreur", "Erreur, puis défaut, puis défaillance", "Erreur, puis défaillance, puis défaut"], a: 2,
    e: "Une erreur (humaine) crée un défaut dans le produit, qui cause une défaillance (échec) en exploitation s'il n'est pas corrigé." },
  { ch: 1, q: "Une défaillance (failure) est :", o: ["Une erreur humaine dans la documentation", "La manifestation d'un défaut dans l'environnement d'exploitation", "Un défaut détecté pendant les tests unitaires", "Une métrique du processus"], a: 1,
    e: "Failure : panne, crash. L'origine d'une panne est un défaut caché. Error : faute humaine. Defect : défaut non détecté pendant le développement, l'AQ ou les tests." },
  { ch: 1, q: "Lequel des échecs logiciels suivants est dû à une mauvaise transcription d'une formule ?", o: ["Mariner 1 (1962)", "Therac-25 (années 1980)", "Missile Patriot (1991)", "Ariane 5 (1996)"], a: 0,
    e: "Mariner 1 : un programmeur a mal transcrit une formule manuscrite. Coût : 18,5 millions de dollars." },
  { ch: 1, q: "Quelle est la cause de l'échec du missile Patriot (1991) ?", o: ["Un calcul inexact du temps dû à des erreurs arithmétiques", "Une unité de mesure confondue", "Une table de division incomplète", "Une faille de chiffrement"], a: 0,
    e: "Le temps depuis le démarrage était mal calculé à cause d'erreurs arithmétiques des ordinateurs : 28 soldats morts, 100 blessés." },
  { ch: 1, q: "Le bug de la division du Pentium (1994) vient de :", o: ["Une mauvaise transcription d'équation", "L'initialisation incomplète d'une table de valeurs servant à la division", "Un débordement d'entier", "Une mise à jour défectueuse"], a: 1,
    e: "Coût : 475 millions de dollars et la crédibilité de l'entreprise." },
  { ch: 1, q: "Le logiciel de radiothérapie de 2000 (8 morts, 20 blessés graves) a mal calculé les doses parce que :", o: ["Les calculs dépendaient de l'ordre de saisie des données, avec parfois des doses saisies deux fois", "Le matériel était défectueux", "Le réseau était coupé", "Les médecins n'avaient pas de formation"], a: 0,
    e: "Les doses calculées dépendaient de l'ordre des saisies, d'où des erreurs dans le calcul suivant." },
  { ch: 1, q: "Heartbleed (OpenSSL, 2014) est :", o: ["Un bug d'arrondi dans une horloge", "Une faille permettant de lire une portion de la mémoire d'un serveur distant", "Un bug de conversion d'unités", "Une panne de réseau électrique"], a: 1,
    e: "Environ 500 000 serveurs web étaient concernés." },
  { ch: 1, q: "Le bug de l'an 2038 se manifeste le :", o: ["1er janvier 2000", "19 janvier 2038 à 3 h 14 min 8 s (temps universel)", "31 décembre 1999", "1er janvier 2038 à minuit"], a: 1,
    e: "Les systèmes affectés croiront alors être le 13 décembre 1901. C'est un bug similaire à celui de l'an 2000." },
  { ch: 1, q: "Quel pourcentage des défauts logiciels vient des trois catégories : structure du code, données et fonctionnalités implémentées ?", o: ["37 %", "50 %", "63 %", "75 %"], a: 2,
    e: "Structurel 25 %, données 22 %, fonctionnalités implémentées 16 %, soit 63 %. Les équipes doivent renforcer les bonnes pratiques de codage, la gestion des données et les tests fonctionnels automatisés." },
  { ch: 1, q: "Sur quels deux piliers repose la qualité logicielle (SWEBOK) ?", o: ["Coût et délais", "Qualité du produit et qualité du processus", "Tests unitaires et revues de code", "Documentation et maintenance"], a: 1,
    e: "Produit : fonctionnalités, fiabilité, efficacité, maintenabilité... Processus : rigueur des pratiques, méthodes et outils." },
  { ch: 1, q: "Quel niveau de besoins correspond aux attentes réelles, mais non exprimées, du client ?", o: ["Besoins spécifiés", "Besoins réalisés", "Besoins exprimés", "Vrais besoins"], a: 3,
    e: "Les quatre niveaux : vrais besoins (esprit des parties prenantes), exprimés (formulés par les utilisateurs), spécifiés (document de spécification), réalisés (documents et code produits)." },
  { ch: 1, q: "Quelle est la cause d'écart typique entre besoins spécifiés et besoins réalisés ?", o: ["Instabilité des exigences", "Tests insuffisants et mauvais usage des méthodes et outils de production", "Différences de points de vue entre le donneur d'ordre et les utilisateurs", "Spécification incomplète"], a: 1,
    e: "Vrais vers exprimés : méconnaissance, instabilité. Exprimés vers spécifiés : spécification incomplète, communication. Spécifiés vers réalisés : méthodes et outils inadaptés, tests insuffisants." },
  { ch: 1, q: "Quel est l'objectif principal de l'Assurance Qualité Logicielle (SQA) ?", o: ["Réduire le nombre de lignes de code", "Accélérer la livraison", "Garantir objectivement que le logiciel répond aux exigences, dans les contraintes de coût et de délai", "Remplacer les tests manuels par des tests automatisés"], a: 2,
    e: "Attribut clé : l'objectivité de la fonction SQA, voire son indépendance organisationnelle vis-à-vis du projet." },
  { ch: 1, q: "Quelle métrique relève des « métriques du produit logiciel » ?", o: ["Nombre de développeurs", "Coût total du projet", "Complexité cyclomatique du code", "Durée du cycle de développement"], a: 2,
    e: "Processus : coût, temps. Produit : code, complexité. Projet : nombre de développeurs, effort." },
  { ch: 1, q: "Lequel n'est PAS un rôle de la métrologie logicielle ?", o: ["Rôle évaluatif", "Rôle vérificatif", "Rôle prédictif", "Rôle marketing"], a: 3,
    e: "Évaluatif : décrire l'objet. Vérificatif : contrôler la conformité. Prédictif : prévoir l'évolution." },
  { ch: 1, q: "Selon l'IEEE, la qualité logicielle est :", o: ["Le nombre de tests passés", "Le degré avec lequel un système, composant ou processus satisfait aux besoins ou attentes de ses clients ou usagers", "L'absence totale de bugs", "La conformité au budget"], a: 1,
    e: "La définition SWEBOK ajoute : besoins explicites et implicites, dans des conditions spécifiées. La pertinence des exigences compte autant que leur respect." },

  // ---------- 2. Modèles de qualité ----------
  { ch: 2, q: "Que représente l'écriture Qualité ≈ f(attributs) ?", o: ["La qualité est indépendante des attributs", "La qualité globale se déduit d'attributs mesurables du logiciel", "La qualité se mesure uniquement par les tests", "La qualité égale le nombre de lignes"], a: 1,
    e: "La fonction f relie les caractéristiques internes mesurables (complexité, fiabilité, maintenabilité...) à la qualité perçue. Elle dépend du contexte et du modèle." },
  { ch: 2, q: "Quelle est la hiérarchie d'un modèle de qualité ?", o: ["Métriques, critères, facteurs, qualité", "Qualité, facteurs, critères, métriques", "Qualité, critères, facteurs, métriques", "Facteurs, qualité, métriques, critères"], a: 1,
    e: "Qualité en haut, décomposée en facteurs, chacun en critères, chacun avec des métriques." },
  { ch: 2, q: "Un facteur de qualité correspond à quelle vision ?", o: ["Interne (développeur)", "Externe (utilisateur)", "Financière", "Contractuelle"], a: 1,
    e: "Facteur : vision externe, qualité ressentie par l'utilisateur. Critère : vision interne, caractéristique sur laquelle le développeur peut agir. Métrique : mesure d'une propriété d'un critère." },
  { ch: 2, q: "Combien de facteurs et de critères le modèle de McCall (1977) définit-il ?", o: ["6 facteurs et 27 critères", "11 facteurs et 23 critères", "8 facteurs et 38 critères", "9 facteurs et 25 critères"], a: 1,
    e: "McCall : 11 facteurs, 23 critères. ISO 9126 : 6 caractéristiques et 27 sous-caractéristiques. ISO 25010:2023 : 9 caractéristiques et 38 sous-caractéristiques." },
  { ch: 2, q: "Quelles sont les trois dimensions de McCall ?", o: ["Opérationnel, évolution, adaptabilité", "Interne, externe, usage", "Produit, processus, projet", "Fonctionnel, technique, humain"], a: 0,
    e: "Opérationnel (conformité aux besoins, fiabilité, efficacité, intégrité, facilité d'emploi), évolution (maintenabilité, souplesse, testabilité), adaptabilité (portabilité, réutilisabilité, interopérabilité)." },
  { ch: 2, q: "Quels facteurs de McCall appartiennent à la dimension « évolution » ?", o: ["Maintenabilité, souplesse, testabilité", "Portabilité, réutilisabilité, interopérabilité", "Fiabilité, efficacité, intégrité", "Facilité d'emploi, conformité"], a: 0,
    e: "Évolution : maintenabilité, souplesse (flexibility), testabilité." },
  { ch: 2, q: "Quels facteurs relèvent de l'adaptabilité chez McCall ?", o: ["Portabilité, réutilisabilité, interopérabilité", "Maintenabilité, testabilité", "Fiabilité, intégrité", "Efficacité, facilité d'emploi"], a: 0,
    e: "Adaptabilité : capacité à passer à un autre environnement ou contexte." },
  { ch: 2, q: "Quelles sont les 6 caractéristiques de l'ISO 9126 ?", o: ["Fonctionnalité, fiabilité, utilisabilité, efficacité, maintenabilité, portabilité", "Fonctionnalité, sécurité, compatibilité, fiabilité, maintenabilité, flexibilité", "Correction, fiabilité, efficacité, intégrité, utilisabilité, testabilité", "Performance, sécurité, coût, délai, qualité, risque"], a: 0,
    e: "ISO 9126 : 6 caractéristiques et 27 sous-caractéristiques." },
  { ch: 2, q: "Que signifie GQM ?", o: ["Global Quality Management", "Goal, Question, Metric", "Good Quality Model", "Group, Quality, Measure"], a: 1,
    e: "Approche de Victor Basili : on part d'un objectif (Goal), on formule des questions, puis on définit les métriques pour y répondre." },
  { ch: 2, q: "Quel est le principe de GQM ?", o: ["Mesurer tout ce qui est mesurable", "Mesurer uniquement ce qui aide à atteindre un objectif", "Mesurer une seule fois en fin de projet", "Remplacer les tests par des mesures"], a: 1,
    e: "On évite de collecter des mesures sans finalité précise." },
  { ch: 2, q: "Quels sont les trois niveaux d'évaluation d'un modèle de qualité ?", o: ["Métriques, critères, facteurs", "Interne, externe, usage", "Mesure, notation, appréciation", "Produit, processus, service"], a: 0,
    e: "Métriques : indicateurs élémentaires comparés à un seuil. Critères : Ic = f(m1, m2, ...). Facteurs : If = g(Ic1, Ic2, ...)." },
  { ch: 2, q: "Quelles sont les trois étapes du processus d'évaluation ?", o: ["Définir les exigences, fixer les métriques, procéder à l'évaluation", "Coder, tester, livrer", "Planifier, mesurer, archiver", "Mesurer, tester, corriger"], a: 0,
    e: "Étape 3 : mesure, notation (note de satisfaction), appréciation (résultat global)." },
  { ch: 2, q: "Le niveau de sévérité d'un bug {mineur, majeur, critique} est une mesure de type :", o: ["Nominal", "Ordinal", "Intervalle", "Ratio"], a: 1,
    e: "Il y a un ordre, mais les écarts entre valeurs ne sont pas mesurables : ordinal." },
  { ch: 2, q: "Le type d'erreur {syntaxique, logique, d'exécution, d'interface} est une mesure de type :", o: ["Nominal", "Ordinal", "Intervalle", "Absolu"], a: 0,
    e: "Simple classement sans ordre : nominal." },
  { ch: 2, q: "Le nombre total d'erreurs détectées est une mesure de type :", o: ["Nominal", "Ordinal", "Ratio", "Absolu"], a: 3,
    e: "L'échelle absolue est un cas particulier du ratio : on compte directement des éléments." },
  { ch: 2, q: "Le taux de couverture des tests (%) est de type :", o: ["Nominal", "Intervalle", "Ratio", "Ordinal"], a: 2,
    e: "Ratio : zéro absolu (aucune couverture) et rapports significatifs. Intervalle : zéro arbitraire, par exemple la température en degrés Celsius." },
  { ch: 2, q: "Quelle transformation est autorisée sur une échelle d'intervalle ?", o: ["t(M) = a·M + b avec a > 0", "t(M) = a·M avec a > 0", "Identité uniquement", "Toute correspondance un-à-un"], a: 0,
    e: "Intervalle : a·M + b (Celsius vers Fahrenheit). Ratio : a·M (conversion de monnaie). Absolue : identité. Ordinale : toute transformation qui préserve l'ordre. Nominale : correspondance un-à-un." },
  { ch: 2, q: "Quelles sont les dimensions de la qualité évaluées par les modèles ?", o: ["Produit, processus, service, ressources", "Interne, externe, usage", "Coût, délai, périmètre", "Code, test, déploiement"], a: 0,
    e: "Produit (caractéristiques du logiciel), processus (méthodes), service (support), ressources (humaines, matérielles, logicielles)." },
  { ch: 2, q: "Quelles sont les deux contraintes des modèles qui attribuent des notes à partir de métriques brutes ?", o: ["Composer des métriques définies différemment et agréger les résultats en une note globale", "Réduire le coût et le délai", "Installer des outils et former les équipes", "Écrire la documentation et les tests"], a: 0,
    e: "Exemple : « facilité de modification » combine LOC, complexité cyclomatique, nombre de méthodes par classe (NMC) et profondeur d'héritage (DIT)." },

  // ---------- 3. ISO 25010 ----------
  { ch: 3, q: "Quelles sont les 3 dimensions de la qualité selon la norme ISO ?", o: ["Interne, externe, usage", "Produit, processus, projet", "Facteur, critère, métrique", "Fonctionnelle, technique, humaine"], a: 0,
    e: "Interne : code et conception, évaluée sans exécuter. Externe : comportement à l'exécution (tests). Usage : expérience en conditions réelles." },
  { ch: 3, q: "La qualité interne se mesure :", o: ["Pendant l'exploitation chez l'utilisateur", "En analysant le code et la conception sans exécuter le logiciel", "Uniquement par questionnaire", "Après la livraison"], a: 1,
    e: "Mesures statiques du code source. Les métriques internes visent des livrables non exécutables (exigences, spécifications, code)." },
  { ch: 3, q: "Quelle est la suite logique des trois types de métriques ?", o: ["Interne, externe, à l'usage (conception et code, tests, utilisation réelle)", "Externe, interne, à l'usage", "À l'usage, interne, externe", "Interne, à l'usage, externe"], a: 0,
    e: "La qualité interne influence la qualité externe, qui influence la qualité à l'usage. Chacune dépend de la suivante en retour." },
  { ch: 3, q: "Combien de caractéristiques compte ISO/IEC 25010:2011 ?", o: ["6", "8", "9", "11"], a: 1,
    e: "9126 : 6. 25010:2011 (SQuaRE) : 8, avec la compatibilité et la sécurité en plus. 25010:2023 : 9." },
  { ch: 3, q: "Qu'est-ce qui change dans ISO/IEC 25010:2023 ?", o: ["L'utilisabilité devient capacité d'interaction, la portabilité devient flexibilité, la safety est ajoutée", "La sécurité est supprimée", "La maintenabilité disparaît", "Il n'y a plus de sous-caractéristiques"], a: 0,
    e: "Résultat : 9 caractéristiques et 38 sous-caractéristiques." },
  { ch: 3, q: "Le temps de réponse relève de quelle caractéristique ?", o: ["Efficacité des performances (comportement temporel)", "Fiabilité", "Compatibilité", "Flexibilité"], a: 0,
    e: "Efficacité des performances : comportement temporel, utilisation des ressources, capacité." },
  { ch: 3, q: "Laquelle est une sous-caractéristique de la maintenabilité ?", o: ["Testabilité", "Confidentialité", "Coexistence", "Scalabilité"], a: 0,
    e: "Maintenabilité : modularité, réutilisabilité, analysabilité, modifiabilité, testabilité." },
  { ch: 3, q: "La non-répudiation est une sous-caractéristique de :", o: ["La sécurité", "La fiabilité", "La compatibilité", "La capacité d'interaction"], a: 0,
    e: "Sécurité : confidentialité, intégrité, non-répudiation, traçabilité, authenticité, résistance." },
  { ch: 3, q: "La disponibilité et la capacité de récupération appartiennent à :", o: ["La fiabilité", "La sécurité", "La flexibilité", "L'adéquation fonctionnelle"], a: 0,
    e: "Fiabilité : infaillibilité, disponibilité, tolérance aux pannes, capacité de récupération." },
  { ch: 3, q: "Coexistence et interopérabilité sont les sous-caractéristiques de :", o: ["La compatibilité", "La flexibilité", "La sécurité", "La maintenabilité"], a: 0,
    e: "Compatibilité : échanger des informations avec d'autres systèmes et partager un environnement." },
  { ch: 3, q: "Adaptabilité, facilité d'installation, remplaçabilité et scalabilité sont les sous-caractéristiques de :", o: ["La flexibilité", "La fiabilité", "La maintenabilité", "La compatibilité"], a: 0,
    e: "Flexibilité : nouvelle caractéristique de premier niveau qui remplace la portabilité." },
  { ch: 3, q: "Quelle caractéristique évalue l'absence de risques inacceptables pour les personnes, l'environnement ou les biens ?", o: ["Safety (sécurité des personnes et des biens)", "Security", "Compatibilité", "Capacité d'interaction"], a: 0,
    e: "Safety : contrainte opérationnelle, identification des risques, comportement fail-safe, avertissement des dangers, intégration sûre. Ne pas confondre avec Security (confidentialité, intégrité...)." },
  { ch: 3, q: "Complétude, correction et pertinence fonctionnelles sont les sous-caractéristiques de :", o: ["L'adéquation fonctionnelle", "La fiabilité", "L'efficacité", "La flexibilité"], a: 0,
    e: "Adéquation fonctionnelle : le logiciel fournit-il les fonctions nécessaires, correctement et de façon pertinente ?" },
  { ch: 3, q: "Quelles sont les sous-caractéristiques de la capacité d'interaction qui visent la diversité des utilisateurs et l'aide intégrée ?", o: ["Inclusivité et assistance utilisateur", "Modularité et testabilité", "Confidentialité et intégrité", "Disponibilité et récupération"], a: 0,
    e: "Capacité d'interaction : reconnaissabilité de la pertinence, facilité d'apprentissage, d'utilisation, protection contre les erreurs, engagement utilisateur, inclusivité, assistance, auto-descriptivité." },
  { ch: 3, q: "ISO/IEC 25059 concerne :", o: ["Les systèmes basés sur l'IA (extension de SQuaRE)", "La sécurité réseau", "La gestion de projet", "L'ergonomie web"], a: 0,
    e: "Elle ajoute explicabilité, équité (absence de biais), robustesse, précision fonctionnelle, adaptabilité et apprentissage continu (dérive du modèle)." },
  { ch: 3, q: "La métrique X = A / B de l'échangeabilité des données, avec 10 formats prévus dont 8 validés, vaut :", o: ["0,8", "1,25", "0,2", "8"], a: 0,
    e: "X = 8 / 10 = 0,8. Plus X est proche de 1, meilleure est l'échangeabilité (0 ≤ X ≤ 1)." },
  { ch: 3, q: "Pour la couverture des tests X = A / B, que représente B ?", o: ["Le nombre de cas de test nécessaires pour couvrir les exigences", "Le nombre de bugs", "Le temps de test", "La taille du code"], a: 0,
    e: "A : cas de test réellement exécutés. Plus X est proche de 1, meilleure est la couverture." },

  // ---------- 4. Métriques de code ----------
  { ch: 4, q: "Que mesurent les métriques de lignes de code (LOC) ?", o: ["La structure du programme, pas sa qualité logique", "L'intelligence du code", "La performance à l'exécution", "La satisfaction de l'utilisateur"], a: 0,
    e: "Elles sont simples à compter et à comprendre, mais ne disent rien sur la qualité logique du code." },
  { ch: 4, q: "LOCphy représente :", o: ["Le nombre de lignes physiques (code, commentaires, lignes vides)", "Le nombre de lignes de commentaires", "Le nombre de lignes vides", "Les lignes de programme seulement"], a: 0,
    e: "LOCpro : lignes de programme. LOCcom : commentaires. LOCbl : lignes vides." },
  { ch: 4, q: "Comment calcule-t-on la densité de commentaires ?", o: ["DC = LOCcom / LOCphy", "DC = LOCcom / LOCpro", "DC = LOCphy / LOCcom", "DC = LOCbl / LOCphy"], a: 0,
    e: "Exemple du cours : 12 lignes de commentaires sur 19 lignes physiques, DC ≈ 0,63. Norme : 0,2 à 0,3." },
  { ch: 4, q: "Quelle plage est recommandée pour la densité de commentaires ?", o: ["0,2 à 0,3", "0,5 à 0,7", "0 à 0,05", "0,8 à 1"], a: 0,
    e: "Bon équilibre entre code et documentation. Trop peu : difficile à comprendre. Trop : redondant." },
  { ch: 4, q: "Un graphe de flot de contrôle (GFC) représente :", o: ["Tous les chemins qui peuvent être suivis pendant l'exécution", "L'architecture réseau", "Les dépendances entre packages", "Les tests réussis"], a: 0,
    e: "Nœuds : instructions (blocs). Arcs : transferts possibles, avec les conditions. Un nœud d'entrée et un nœud de sortie." },
  { ch: 4, q: "Quelle est la formule de la complexité cyclomatique de McCabe ?", o: ["V(G) = E - N + 2P", "V(G) = E + N + 2P", "V(G) = N - E + P", "V(G) = E / N"], a: 0,
    e: "E : arêtes, N : nœuds, P : composantes connexes (1 pour un programme). Forme directe : C = π + 1, avec π le nombre de décisions." },
  { ch: 4, q: "Une instruction CASE qui traite N cas compte pour :", o: ["N - 1 décisions", "N décisions", "1 décision", "N + 1 décisions"], a: 0,
    e: "IF : 1 décision. FOR ou WHILE : 1 décision. CASE à N cas : N - 1." },
  { ch: 4, q: "Quelle est la valeur minimale de la complexité cyclomatique d'une méthode ?", o: ["0", "1", "2", "5"], a: 1,
    e: "Il y a toujours au moins un chemin." },
  { ch: 4, q: "Une complexité cyclomatique de 35 correspond à :", o: ["Procédure simple, risque faible", "Procédure plus complexe, risque modéré", "Procédure complexe, risque élevé", "Code non testable, risque très élevé"], a: 2,
    e: "1 à 10 : simple, risque faible. 11 à 20 : plus complexe, modéré. 21 à 50 : complexe, élevé. Plus de 50 : non testable, très élevé." },
  { ch: 4, q: "À quoi sert surtout le nombre cyclomatique ?", o: ["À estimer l'effort de test (nombre minimal de cas de test pour une couverture complète)", "À mesurer la beauté du code", "À compter les commentaires", "À mesurer la vitesse"], a: 0,
    e: "Plus il est grand, plus il y a de chemins, plus la fonction est difficile à comprendre et à tester. La valeur maximale peut être fixée dans le plan qualité." },
  { ch: 4, q: "Dans les métriques de Halstead, que sont les opérandes ?", o: ["Les jetons qui contiennent une valeur (variables, constantes)", "Les virgules et parenthèses", "Les mots-clés uniquement", "Les commentaires"], a: 0,
    e: "Opérateurs : tout le reste (virgules, parenthèses, opérateurs arithmétiques, mots-clés...)." },
  { ch: 4, q: "Pour a := a + 1; combien d'opérateurs et d'opérandes ?", o: ["3 opérateurs (+, :=, ;) et 2 opérandes (a, 1)", "2 opérateurs et 3 opérandes", "1 opérateur et 2 opérandes", "4 opérateurs et 1 opérande"], a: 0,
    e: "Exemple du cours." },
  { ch: 4, q: "Quelle est la formule du volume de Halstead ?", o: ["V = N · log2(n)", "V = n · log2(N)", "V = N + n", "V = N1 · N2"], a: 0,
    e: "n = n1 + n2 (vocabulaire), N = N1 + N2 (longueur). Le volume s'exprime en bits." },
  { ch: 4, q: "Comment calcule-t-on le niveau de difficulté de Halstead ?", o: ["D = (n1 / 2) × (N2 / n2)", "D = (n2 / 2) × (N1 / n1)", "D = n1 / n2", "D = N / n"], a: 0,
    e: "Plus il y a d'opérateurs uniques (et d'opérandes répétés), plus le programme est difficile. Le niveau du programme est L = 1 / D." },
  { ch: 4, q: "Quelles formules donnent l'effort, le temps et le nombre de bugs de Halstead ?", o: ["E = V × D, T = E / 18, B = E^(2/3) / 3000", "E = V + D, T = E × 18, B = V / 3000", "E = N × n, T = E / 60, B = E / 3000", "E = D / V, T = E / 18, B = V^2 / 3000"], a: 0,
    e: "S = 18 est la constante de Stroud (décisions élémentaires par seconde du cerveau humain). 3000 est un facteur empirique de calibration." },
  { ch: 4, q: "Qui a introduit la complexité cyclomatique et quand ? Et Halstead ?", o: ["McCabe en 1976, Halstead en 1977", "Halstead en 1976, McCabe en 1977", "McCabe en 1994, Halstead en 1990", "Les deux en 1977"], a: 0,
    e: "McCabe : 1976. Halstead : 1977. Chidamber et Kemerer (métriques objet) : 1994." },

  // ---------- 5. Métriques POO ----------
  { ch: 5, q: "Quelles sont les 6 métriques de Chidamber et Kemerer (1994) ?", o: ["WMC, DIT, NOC, CBO, RFC, LCOM", "LOC, DC, V(G), E, B, T", "A, I, D, Ca, Ce, SI", "S, O, L, I, D, P"], a: 0,
    e: "SI, A, I et D ne sont pas dans CK : ce sont l'indice de spécialisation et les métriques de Robert Martin." },
  { ch: 5, q: "Que signifie SOLID pour la lettre O ?", o: ["Open/Closed : ouvert à l'extension, fermé à la modification", "Object only", "Optimized loading", "One class only"], a: 0,
    e: "S : Single Responsibility. L : Liskov Substitution. I : Interface Segregation. D : Dependency Inversion." },
  { ch: 5, q: "WMC se calcule par :", o: ["La somme des complexités des méthodes de la classe", "Le nombre de sous-classes", "La profondeur d'héritage", "Le nombre de classes couplées"], a: 0,
    e: "WMC = somme des Ci. Si chaque méthode vaut 1, WMC = nombre de méthodes (la classe foo du cours a WMC = 4)." },
  { ch: 5, q: "En Java, quelle est la valeur minimale de DIT ?", o: ["0", "1", "2", "3"], a: 1,
    e: "Toutes les classes héritent de Object. DIT est la distance maximale jusqu'à la racine." },
  { ch: 5, q: "NOC mesure :", o: ["Le nombre de sous-classes directes d'une classe", "Le nombre total de descendants", "Le nombre de méthodes", "Le couplage"], a: 0,
    e: "Exemple : NOC(B1) = 2 pour deux enfants C1 et C2." },
  { ch: 5, q: "Comment calcule-t-on l'indice de spécialisation SI ?", o: ["SI = NORM × DIT / NOM", "SI = NOM × DIT / NORM", "SI = NORM / (DIT × NOM)", "SI = NOM / NORM"], a: 0,
    e: "NORM : méthodes redéfinies. DIT : profondeur. NOM : nombre total de méthodes. Faible (≈ 0), moyen (≈ 0,5 à 1), élevé (> 1,5)." },
  { ch: 5, q: "Une classe avec SI = 3 est :", o: ["Très spécialisée : refactorisation conseillée", "Générique et flexible", "Équilibrée", "Sans héritage"], a: 0,
    e: "SI > 1,5 : classe très spécialisée, qui redéfinit beaucoup. Risque de rigidité. Le cours conseille d'implémenter une interface plutôt que d'hériter." },
  { ch: 5, q: "CBO mesure :", o: ["Le nombre de classes couplées avec la classe étudiée", "La cohésion", "La profondeur d'héritage", "Le nombre de réponses possibles"], a: 0,
    e: "Fort couplage : classe plus complexe, moins réutilisable, plus difficile à modifier et à maintenir." },
  { ch: 5, q: "RFC est égal à :", o: ["|RS|, l'ensemble des méthodes de la classe et des méthodes directement appelées", "Le nombre de méthodes de la classe seulement", "Le nombre d'attributs", "La somme des CBO"], a: 0,
    e: "Exemple : C1 a 3 méthodes dont une appelle C2.M1 : RFC(C1) = 3 + 1 = 4." },
  { ch: 5, q: "Comment se calcule LCOM ?", o: ["LCOM = P - Q si P > Q, sinon 0", "LCOM = Q - P", "LCOM = P + Q", "LCOM = P / Q"], a: 0,
    e: "P : paires de méthodes sans attribut commun. Q : paires avec au moins un attribut commun. Petit LCOM : classe cohésive." },
  { ch: 5, q: "Trois méthodes M1 {a,b,c,d,e}, M2 {a,b,c}, M3 {x,y,z}. LCOM ?", o: ["1", "2", "3", "0"], a: 0,
    e: "Paires : (M1,M2) partage, (M1,M3) et (M2,M3) ne partagent pas. P = 2, Q = 1, LCOM = 2 - 1 = 1." },
  { ch: 5, q: "Quelles sont les valeurs de référence faibles du cours : WMC, DIT, CBO, RFC ?", o: ["WMC 0-10, DIT 0-4, CBO 0-5, RFC 0-20", "WMC 0-50, DIT 0-10, CBO 0-20, RFC 0-100", "WMC 0-5, DIT 0-1, CBO 0-2, RFC 0-5", "WMC 0-20, DIT 0-7, CBO 0-10, RFC 0-50"], a: 0,
    e: "NOC : 0 à 3 normal. LCOM : 0 à 1 forte cohésion. Au-dessus : WMC > 20, DIT > 7, NOC > 7, CBO > 10, RFC > 50 sont élevés." },
  { ch: 5, q: "Les métriques CK mesurent :", o: ["La qualité locale des classes (complexité, couplage, cohésion)", "L'architecture globale des packages", "Le processus de développement", "La satisfaction utilisateur"], a: 0,
    e: "Pour l'échelle des packages, on utilise les métriques de Robert Martin : abstractivité et instabilité." },
  { ch: 5, q: "L'abstractivité A d'un package est :", o: ["Nabstrait / Ntotal (classes abstraites et interfaces sur le total)", "Ce / (Ca + Ce)", "|A + I - 1|", "Ca + Ce"], a: 0,
    e: "A proche de 0 : package concret. A proche de 1 : package abstrait." },
  { ch: 5, q: "Quelle est la formule de l'instabilité I ?", o: ["I = Ce / (Ca + Ce)", "I = Ca / (Ca + Ce)", "I = Ce × Ca", "I = Ca - Ce"], a: 0,
    e: "Ca : classes extérieures qui dépendent de ce module (entrant). Ce : classes dont ce module dépend (sortant). I proche de 0 : stable, difficile à changer. I proche de 1 : instable, facile à changer." },
  { ch: 5, q: "Comment se calcule la distance à la séquence principale ?", o: ["D = |A + I - 1|", "D = A + I", "D = A × I", "D = |A - I|"], a: 0,
    e: "D est entre 0 et 1. Plus D est proche de 0, mieux le package est conçu (sur la droite A + I = 1)." },
  { ch: 5, q: "Un package avec A = 0 et I = 0,1 (D = 0,9) est :", o: ["Concret et stable : trop rigide", "Abstrait et instable : bien conçu", "Équilibré", "Parfait"], a: 0,
    e: "Concret (aucune abstraction) et stable (beaucoup en dépendent) : toute modification risque de casser d'autres composants." },
  { ch: 5, q: "Classes Forme (Ca = 2, Ce = 0), Rectangle (1, 1), Cercle (0, 1). Quelles instabilités ?", o: ["0, 0,5, 1", "1, 0,5, 0", "0,5, 0,5, 0,5", "2, 1, 0"], a: 0,
    e: "Forme : 0/2 = 0 (très stable). Rectangle : 1/2 = 0,5. Cercle : 1/1 = 1 (très instable)." },

  // ---------- 6. SonarQube et TP ----------
  { ch: 6, q: "SonarQube est :", o: ["Une solution web open source de gestion centralisée de la qualité du code, multi-langages (plus de 25)", "Un compilateur Java", "Un outil de gestion de projet", "Un système de base de données"], a: 0,
    e: "Il s'intègre aux outils CI (Jenkins, TravisCI, Azure DevOps), notifie succès ou échec et est sécurisé par RBAC (Role-Based Access Control)." },
  { ch: 6, q: "Parmi ces éléments, lequel n'est PAS un des 7 axes de qualité de SonarQube ?", o: ["Coût du projet", "Duplications", "Complexité", "Documentation et commentaires"], a: 0,
    e: "Les 7 axes : respect des standards, anomalies potentielles, complexité, duplications, architecture et design (code spaghetti), manque de tests unitaires, documentation et commentaires." },
  { ch: 6, q: "Vers quelle valeur doit tendre le taux de duplication ?", o: ["Vers 0", "Vers 50 %", "Vers 100 %", "Il n'a pas d'importance"], a: 0,
    e: "Duplication : forte probabilité d'anomalies et code inutile, donc refactoring." },
  { ch: 6, q: "Quelle est la différence entre complexité cyclomatique et complexité cognitive ?", o: ["La cyclomatique compte les chemins linéairement indépendants, la cognitive qualifie l'effort nécessaire pour comprendre le code (SonarSource, 2016)", "Elles sont identiques", "La cognitive compte les lignes", "La cyclomatique mesure le temps d'exécution"], a: 0,
    e: "La complexité cognitive s'affranchit de tout fondement mathématique." },
  { ch: 6, q: "Quels sont les niveaux de gravité d'une anomalie dans SonarQube ?", o: ["Bloquant, critique, majeur, mineur, info", "Haut, moyen, bas", "Fatal, erreur, avertissement", "P1, P2, P3"], a: 0,
    e: "Le tableau de bord donne aussi le temps estimé de correction." },
  { ch: 6, q: "Que répond le Quality Gate ?", o: ["Puis-je livrer mon projet en production aujourd'hui ? (PASSED ou FAILED)", "Combien de lignes contient le projet ?", "Qui a écrit le code ?", "Quelle version utiliser ?"], a: 0,
    e: "Il se base notamment sur l'absence d'anomalies bloquantes, une couverture de code supérieure à 80 % et d'autres indicateurs de sécurité, fiabilité et maintenabilité." },
  { ch: 6, q: "Lesquelles sont des « anomalies » pouvant provoquer des plantages ?", o: ["Ressources non fermées, boucles infinies, mauvais usage de classes", "Noms de variables trop longs", "Commentaires trop nombreux", "Lignes vides"], a: 0,
    e: "Autres exemples : new BigDecimal(double), création d'exception sans throw." },
  { ch: 6, q: "Dans le TP SonarQube, comment lance-t-on le serveur et où y accède-t-on ?", o: ["StartSonar.bat puis http://localhost:9000/", "sonar-scanner.bat puis http://localhost:8080/", "javac puis http://localhost:3000/", "mvn install puis http://localhost:27017/"], a: 0,
    e: "Ensuite : créer un projet (nom, clé), générer un token, mettre le token dans sonar-project.properties, compiler en bin/, exécuter sonar-scanner.bat." },
  { ch: 6, q: "Dans le TP, à quoi sert le token généré dans SonarQube ?", o: ["À autoriser le scanner à envoyer l'analyse au serveur (il va dans sonar-project.properties)", "À compiler le projet", "À installer Java", "À créer le rapport PDF"], a: 0,
    e: "Il remplace <VOTRE_TOKEN_SONAR> dans le fichier de propriétés. Prérequis : Java 17 ou plus, SonarQube Community 25.10.0 ou plus, SonarScanner." },
  { ch: 6, q: "Quel outil le TP des métriques POO utilise-t-il pour calculer WMC, DIT, NOC, CBO, RFC, LCOM ?", o: ["CKJM (ckjm-1.8.jar)", "SonarQube", "JUnit", "Maven"], a: 0,
    e: "On compile avec javac vers bin/, puis on lance ckjm sur les .class et on redirige vers metrics.txt." },
  { ch: 6, q: "Dans le TP CKJM, quelles colonnes contient metrics.txt ?", o: ["Classe, WMC, DIT, NOC, CBO, RFC, LCOM, Ca, NPM", "Classe, LOC, DC, V(G)", "Classe, A, I, D", "Classe, bugs, smells, duplications"], a: 0,
    e: "Le tableau du TP demande aussi Ce (couplage sortant, instabilité)." },
  { ch: 6, q: "Selon le TP, que fait l'extraction de méthode sur les métriques ?", o: ["Elle diminue WMC", "Elle augmente WMC", "Elle diminue DIT", "Elle augmente CBO"], a: 0,
    e: "Encapsulation d'attributs : diminue CBO. Fusion ou découpage de classes : diminue LCOM. Introduction d'interfaces : augmente l'abstraction (A) et diminue l'instabilité (I)." },
  { ch: 6, q: "Dans le TD1 (Autopsie d'un échec logiciel), que doit contenir le rapport ?", o: ["Présentation du cas, erreur/défaut/défaillance, impacts, mesures SQA, références (1 page PDF)", "Un programme complet", "Un tableau de métriques CK", "Un projet SonarQube"], a: 0,
    e: "Il faut relier les mesures SQA aux phases du cycle de vie (SDLC)." },

  // ---------- 7. Calculs ----------
  { ch: 7, q: "Un graphe de contrôle a E = 12 arêtes et N = 11 nœuds (P = 1). Que vaut V(G) ?", o: ["3", "2", "23", "1"], a: 0,
    e: "V(G) = E - N + 2P = 12 - 11 + 2 = 3. C'est l'exemple du cours (avec π = 2 décisions, C = 3)." },
  { ch: 7, q: "Un code contient 1 for, 2 if et 1 else. Quelle est la complexité de McCabe ?", o: ["4", "5", "3", "2"], a: 0,
    e: "π = 1 (for) + 2 (if) = 3. Le else ne compte pas. C = π + 1 = 4." },
  { ch: 7, q: "Un programme a n1 = 8, n2 = 5, N1 = 14, N2 = 11. Que valent n et N ?", o: ["n = 13 et N = 25", "n = 13 et N = 24", "n = 22 et N = 13", "n = 25 et N = 13"], a: 0,
    e: "n = 8 + 5 = 13 et N = 14 + 11 = 25. La slide du cours écrit N = 24 : c'est une faute de calcul (14 + 11 = 25)." },
  { ch: 7, q: "Avec les valeurs précédentes, quel est le volume V ?", o: ["Environ 92,5 bits", "Environ 88,8 bits", "Environ 325 bits", "Environ 13 bits"], a: 0,
    e: "V = N · log2(n) = 25 × log2(13) = 25 × 3,70 ≈ 92,5 (24 × 3,70 ≈ 88,8 si on garde la valeur erronée de la slide)." },
  { ch: 7, q: "Même programme : difficulté D = (n1/2)(N2/n2) ?", o: ["8,8", "4", "2,2", "13"], a: 0,
    e: "D = (8/2) × (11/5) = 4 × 2,2 = 8,8." },
  { ch: 7, q: "Un effort E = 814 (en unités Halstead). Temps estimé T ?", o: ["Environ 45 secondes", "Environ 814 secondes", "Environ 14 secondes", "Environ 4 secondes"], a: 0,
    e: "T = E / 18 = 814 / 18 ≈ 45 s." },
  { ch: 7, q: "Un fichier de 20 lignes physiques contient 5 lignes de commentaires. DC ?", o: ["0,25", "0,5", "4", "0,05"], a: 0,
    e: "DC = 5 / 20 = 0,25, dans la plage 0,2 à 0,3." },
  { ch: 7, q: "Une classe a 3 méthodes de complexités 2, 4 et 5. WMC ?", o: ["11 (niveau moyen)", "3", "5", "40"], a: 0,
    e: "WMC = 2 + 4 + 5 = 11 : entre 11 et 20, niveau moyen." },
  { ch: 7, q: "Une classe a P = 2 paires sans attribut commun et Q = 3 paires avec attribut commun. LCOM ?", o: ["0", "-1", "1", "5"], a: 0,
    e: "Comme P < Q, LCOM = 0 : classe cohésive." },
  { ch: 7, q: "Une classe a 5 méthodes propres et appelle 3 méthodes externes. RFC ?", o: ["8", "5", "3", "15"], a: 0,
    e: "RFC = 5 + 3 = 8 (niveau faible, 0 à 20)." },
  { ch: 7, q: "NORM = 2, DIT = 3, NOM = 4. Que vaut SI ?", o: ["1,5", "6", "0,5", "24"], a: 0,
    e: "SI = 2 × 3 / 4 = 1,5. Cas limite : élevé au-delà de 1,5." },
  { ch: 7, q: "Un package a Ca = 3 et Ce = 1. Que vaut son instabilité ?", o: ["0,25", "0,75", "3", "1"], a: 0,
    e: "I = Ce / (Ca + Ce) = 1 / 4 = 0,25 : plutôt stable." },
  { ch: 7, q: "Un package a A = 0,5 et I = 0,5. Que vaut D ?", o: ["0", "0,5", "1", "0,25"], a: 0,
    e: "D = |0,5 + 0,5 - 1| = 0 : sur la séquence principale, idéal." },
  { ch: 7, q: "Étude de cas : Auto-documentation = 0,5 × Commentaires + 0,5 × Noms de variables. Avec Commentaires = 1 et Noms = 0 ?", o: ["0,5", "1", "0", "0,25"], a: 0,
    e: "0,5 × 1 + 0,5 × 0 = 0,5." },
  { ch: 7, q: "Même étude de cas : Simplicité = 0,4 × Commentaires + 0,4 × Complexité + 0,2 × Lignes, avec 1, 2, 1. Valeur ?", o: ["1,4", "1,33", "4", "0,4"], a: 0,
    e: "0,4 + 0,8 + 0,2 = 1,4. Ensuite Maintenabilité = 0,6 × 1,4 + 0,4 × 0,5 = 1,04 et Fiabilité = 1,4." },
  { ch: 7, q: "Sur 60 cas de test requis, 45 ont été exécutés. Couverture X = A / B ?", o: ["0,75", "1,33", "0,45", "15"], a: 0,
    e: "X = 45 / 60 = 0,75. Plus X est proche de 1, meilleure est la couverture." }
];

window.QA = [
  { ch: 1, q: "Quelle différence entre erreur, défaut et défaillance ?",
    a: "<ul><li>Erreur (error) : faute humaine, dans la documentation, le code, la logique, n'importe où dans le cycle de vie.</li><li>Défaut (defect, fault) : erreur humaine non détectée lors du développement, de l'AQ ou des tests, présente dans le produit.</li><li>Défaillance (failure) : manifestation du défaut en exploitation, le système ne remplit plus sa fonction.</li></ul><p>Phrase clé : les erreurs créent des défauts, qui causent des échecs s'ils ne sont pas corrigés. Plus on détecte tôt, moins cela coûte cher.</p>",
    tip: "<p>Erreur (humain), puis défaut (produit), puis défaillance (exploitation). Le bug désigne de façon vague les défaillances.</p>" },
  { ch: 1, q: "Comment définit-on la qualité logicielle ?",
    a: "<p>Le degré auquel un produit logiciel satisfait les exigences établies, explicites ou implicites, dans des conditions spécifiées (SWEBOK, ISO, IEEE). Elle repose sur deux piliers : la qualité du produit (fonctionnalités, fiabilité, maintenabilité...) et la qualité du processus (méthodes, outils, rigueur). Elle dépend aussi de la pertinence des exigences : elles doivent refléter les vrais besoins des parties prenantes.</p>" },
  { ch: 1, q: "Quels sont les quatre niveaux de besoins et les causes d'écart ?",
    a: "<div class='tw'><table><tr><th>Niveau</th><th>Origine</th><th>Causes d'écart avec le suivant</th></tr><tr><td>Vrais besoins</td><td>Esprit des parties prenantes</td><td>Mauvaise connaissance des besoins, exigences instables, points de vue différents</td></tr><tr><td>Exprimés</td><td>Formulés par les utilisateurs</td><td>Spécification incomplète, absence de normes, communication difficile, contrôle qualité insuffisant</td></tr><tr><td>Spécifiés</td><td>Document de spécification</td><td>Méthodes et outils inadaptés, tests insuffisants, contrôle qualité insuffisant</td></tr><tr><td>Réalisés</td><td>Documents et code produits</td><td></td></tr></table></div>" },
  { ch: 1, q: "Qu'est-ce que l'assurance qualité logicielle (SQA) ?",
    a: "<p>Ensemble d'activités qui définissent et évaluent l'adéquation des processus logiciels, pour établir la confiance que ces processus produisent des logiciels de qualité adaptée. Son attribut clé est l'objectivité : la fonction SQA peut être indépendante du projet, à l'abri des pressions techniques, managériales et financières. Elle réduit le risque de produire un logiciel qui ne répond pas aux besoins, dans les limites du budget et du calendrier. Elle implique de planifier la qualité, des activités systématiques tout au long du cycle de vie, une politique d'amélioration continue et des techniques qui démontrent le niveau atteint.</p>" },
  { ch: 1, q: "Pourquoi la qualité des logiciels est-elle importante ? Donner des exemples.",
    a: "<p>Pour la fiabilité, la sûreté et la sécurité (transports, nucléaire, médical, e-commerce) et pour des raisons économiques : coût de correction, rappel de matériel, atteinte à l'image, retard de mise sur le marché, vies humaines.</p><ul><li>Mariner 1 (1962) : formule mal transcrite, 18,5 M$.</li><li>Patriot (1991) : calcul du temps inexact, 28 morts.</li><li>Pentium (1994) : table de division incomplète, 475 M$.</li><li>Radiothérapie (2000) : doses dépendant de l'ordre de saisie, 8 morts.</li><li>Heartbleed (2014) : 500 000 serveurs.</li><li>Tesla Autopilot (2022) : erreurs de détection IA, plus de 3 Md$.</li></ul>" },
  { ch: 1, q: "Qu'est-ce que la métrologie du logiciel ? Quels types de métriques ?",
    a: "<p>Ensemble de méthodes pour mesurer et avoir confiance dans les résultats afin d'évaluer la qualité. Rôles de la mesure : évaluatif, vérificatif, prédictif. Une métrique quantifie une propriété du logiciel.</p><ul><li>Métriques de processus : coût, temps.</li><li>Métriques de produit : code, complexité.</li><li>Métriques de projet : nombre de développeurs, effort.</li></ul>" },
  { ch: 2, q: "Qu'est-ce qu'un modèle de qualité ? Quelle est sa structure ?",
    a: "<p>Il relie les caractéristiques mesurables d'un logiciel à son niveau de qualité : Qualité ≈ f(attributs). Structure : qualité, facteurs, critères, métriques.</p><ul><li>Facteur : caractéristique ressentie par l'utilisateur (vision externe).</li><li>Critère : attribut sur lequel le développeur agit (vision interne).</li><li>Métrique : mesure d'une propriété d'un critère (par exemple la taille d'un module pour le critère simplicité).</li></ul>" },
  { ch: 2, q: "Présenter le modèle de McCall.",
    a: "<p>Premier modèle de qualité (1977) : facteurs, critères, métriques. 11 facteurs et 23 critères.</p><div class='tw'><table><tr><th>Dimension</th><th>Facteurs</th></tr><tr><td>Opérationnel</td><td>Conformité aux besoins (correction), fiabilité, efficacité, intégrité, facilité d'emploi</td></tr><tr><td>Évolution</td><td>Maintenabilité, souplesse, testabilité</td></tr><tr><td>Adaptabilité</td><td>Portabilité, réutilisabilité, interopérabilité</td></tr></table></div>" },
  { ch: 2, q: "Présenter ISO 9126 et son évolution vers ISO 25010.",
    a: "<ul><li>ISO/IEC 9126 (1991 à 2001) : 6 caractéristiques (fonctionnalité, fiabilité, utilisabilité, efficacité, maintenabilité, portabilité) et 27 sous-caractéristiques.</li><li>ISO/IEC 25010:2011 (SQuaRE) : 8 caractéristiques, avec compatibilité et sécurité en premier niveau.</li><li>ISO/IEC 25010:2023 : 9 caractéristiques et 38 sous-caractéristiques. Utilisabilité devient capacité d'interaction, portabilité devient flexibilité, ajout de la safety.</li></ul>" },
  { ch: 2, q: "Expliquer l'approche GQM.",
    a: "<p>GQM (Goal, Question, Metric), de Victor Basili : on définit les métriques à partir des objectifs réels plutôt que de mesurer sans finalité.</p><ol><li>Goal : ce que l'on veut améliorer ou évaluer.</li><li>Question : questions permettant de vérifier que l'objectif est atteint.</li><li>Metric : indicateurs mesurables pour y répondre.</li></ol><p>Principe : mesurer uniquement ce qui aide à atteindre un objectif.</p>" },
  { ch: 2, q: "Comment évalue-t-on la qualité avec un modèle ? Décrire les niveaux et les étapes.",
    a: "<p>Trois niveaux : métriques (comparées à un seuil), critères Ic = f(m1, m2, ...), facteurs If = g(Ic1, Ic2, ...).</p><ol><li>Définir les exigences : facteurs et critères.</li><li>Fixer les métriques : sélection, définition des taux de satisfaction (échelles découpées en niveaux), références et critères d'appréciation.</li><li>Évaluer : mesure (valeurs), notation (note de satisfaction), appréciation (résultat global).</li></ol><p>Difficultés : composer des métriques hétérogènes et agréger les résultats en une note.</p>" },
  { ch: 2, q: "Quels sont les types de mesure de Stevens ?",
    a: "<div class='tw'><table><tr><th>Échelle</th><th>Idée</th><th>Exemples</th><th>Transformation</th></tr><tr><td>Nominale</td><td>Nommer, sans ordre</td><td>Type d'erreur, langage</td><td>Un-à-un</td></tr><tr><td>Ordinale</td><td>Ordre, écarts non mesurables</td><td>Sévérité d'un bug, satisfaction</td><td>Préserve l'ordre</td></tr><tr><td>Intervalle</td><td>Écarts mesurables, zéro arbitraire</td><td>Température, score 0-100</td><td>a·M + b (a &gt; 0)</td></tr><tr><td>Ratio</td><td>Zéro absolu, rapports significatifs</td><td>Âge, taux de couverture</td><td>a·M (a &gt; 0)</td></tr><tr><td>Absolue</td><td>Comptage</td><td>Nombre d'erreurs</td><td>Identité</td></tr></table></div>" },
  { ch: 3, q: "Quelles sont les trois dimensions de la qualité ISO et leurs métriques ?",
    a: "<ul><li>Qualité interne (code et conception) : mesures statiques, sans exécution. Métriques internes sur exigences, spécifications, code, pour prédire la qualité finale et corriger tôt.</li><li>Qualité externe (comportement) : mesures à l'exécution pendant les tests.</li><li>Qualité d'usage (expérience utilisateur) : en conditions réelles. Mesure efficacité, productivité, sécurité, satisfaction.</li></ul><p>La qualité interne influence l'externe, qui influence la qualité à l'usage.</p>" },
  { ch: 3, q: "Citer les 9 caractéristiques d'ISO/IEC 25010:2023 et leurs sous-caractéristiques.",
    a: "<div class='tw'><table><tr><th>Caractéristique</th><th>Sous-caractéristiques</th></tr><tr><td>Adéquation fonctionnelle</td><td>Complétude, correction, pertinence</td></tr><tr><td>Efficacité des performances</td><td>Comportement temporel, utilisation des ressources, capacité</td></tr><tr><td>Compatibilité</td><td>Coexistence, interopérabilité</td></tr><tr><td>Capacité d'interaction</td><td>Reconnaissabilité de la pertinence, facilité d'apprentissage, d'utilisation, protection contre les erreurs, engagement, inclusivité, assistance, auto-descriptivité</td></tr><tr><td>Fiabilité</td><td>Infaillibilité, disponibilité, tolérance aux pannes, capacité de récupération</td></tr><tr><td>Sécurité</td><td>Confidentialité, intégrité, non-répudiation, traçabilité, authenticité, résistance</td></tr><tr><td>Maintenabilité</td><td>Modularité, réutilisabilité, analysabilité, modifiabilité, testabilité</td></tr><tr><td>Flexibilité</td><td>Adaptabilité, facilité d'installation, remplaçabilité, scalabilité</td></tr><tr><td>Sécurité des personnes et des biens (Safety)</td><td>Contrainte opérationnelle, identification des risques, fail-safe, avertissement des dangers, intégration sûre</td></tr></table></div>",
    tip: "<p>Si on compte les sous-caractéristiques listées dans la slide (3, 3, 2, 8, 4, 6, 5, 4, 5), on trouve 40, alors que le texte annonce 38. Pour l'examen, retenez le chiffre du cours : 9 caractéristiques et 38 sous-caractéristiques.</p>" },
  { ch: 3, q: "Donner un exemple de métrique ISO avec sa formule.",
    a: "<ul><li>Échangeabilité des données : X = A / B, avec A formats d'échange validés et B formats à échanger. Exemple 8 sur 10 : X = 0,8.</li><li>Couverture des tests : X = A / B, A cas de test exécutés, B cas de test nécessaires. Densité de test Y = A / C (C : taille du produit).</li><li>Temps de réponse : T = temps d'obtention du résultat moins heure d'entrée de la commande.</li></ul><p>0 ≤ X ≤ 1, plus X est proche de 1, mieux c'est.</p>" },
  { ch: 4, q: "Citer les métriques de lignes de code et leurs normes.",
    a: "<div class='tw'><table><tr><th>Métrique</th><th>Sens</th><th>Norme</th></tr><tr><td>LOCphy</td><td>Lignes physiques</td><td>200 à 500 par fichier</td></tr><tr><td>LOCpro</td><td>Lignes de programme</td><td>50 à 300 par classe</td></tr><tr><td>LOCcom</td><td>Commentaires</td><td>10 à 30 % du code</td></tr><tr><td>LOCbl</td><td>Lignes vides</td><td>10 à 20 % du code</td></tr><tr><td>DC = LOCcom / LOCphy</td><td>Densité de commentaires</td><td>0,2 à 0,3</td></tr></table></div>" },
  { ch: 4, q: "Qu'est-ce que la complexité cyclomatique ? Comment la calcule-t-on ?",
    a: "<p>Nombre de chemins linéairement indépendants d'une méthode (McCabe, 1976), indépendante du langage.</p><ul><li>V(G) = E - N + 2P (E arêtes, N nœuds, P composantes connexes, 1 en général).</li><li>C = π + 1 (π : décisions). IF : 1, FOR ou WHILE : 1, CASE à N cas : N - 1.</li></ul><p>Minimum 1. Elle estime l'effort de test (nombre de cas de test) et la couverture à atteindre.</p>" },
  { ch: 4, q: "Comment interpréter la complexité cyclomatique ?",
    a: "<div class='tw'><table><tr><th>V(G)</th><th>Interprétation</th><th>Risque</th><th>Probabilité de mauvaise correction</th></tr><tr><td>1 à 10</td><td>Procédure simple</td><td>Faible</td><td>5 %</td></tr><tr><td>11 à 20</td><td>Plus complexe</td><td>Modéré</td><td>20 % (vers 20 à 30)</td></tr><tr><td>21 à 50</td><td>Complexe</td><td>Élevé</td><td>40 % (au-delà de 50)</td></tr><tr><td>Plus de 50</td><td>Code non testable</td><td>Très élevé</td><td>60 % (vers 100)</td></tr></table></div>" },
  { ch: 4, q: "Donner les formules de Halstead.",
    a: "<ul><li>n1, n2 : opérateurs et opérandes uniques. N1, N2 : occurrences totales.</li><li>Vocabulaire n = n1 + n2. Longueur N = N1 + N2.</li><li>Volume V = N · log2(n).</li><li>Difficulté D = (n1 / 2) × (N2 / n2). Niveau L = 1 / D.</li><li>Effort E = V × D.</li><li>Temps T = E / 18 (secondes, constante de Stroud).</li><li>Bugs B = E^(2/3) / 3000.</li></ul>" },
  { ch: 5, q: "Présenter les six métriques CK.",
    a: "<div class='tw'><table><tr><th>Métrique</th><th>Mesure</th><th>Bon niveau</th></tr><tr><td>WMC</td><td>Complexité de la classe (somme des complexités des méthodes)</td><td>0 à 10 faible, plus de 20 élevé</td></tr><tr><td>DIT</td><td>Profondeur d'héritage</td><td>0 à 4 acceptable, plus de 7 profond</td></tr><tr><td>NOC</td><td>Nombre de sous-classes directes</td><td>0 à 3 normal, plus de 7 élevé</td></tr><tr><td>CBO</td><td>Couplage entre classes</td><td>0 à 5 faible, plus de 10 élevé</td></tr><tr><td>RFC</td><td>Méthodes exécutables en réponse à un message</td><td>0 à 20 faible, plus de 50 élevé</td></tr><tr><td>LCOM</td><td>Manque de cohésion des méthodes</td><td>0 à 1 forte cohésion</td></tr></table></div>" },
  { ch: 5, q: "Expliquer LCOM avec un exemple.",
    a: "<p>Ii : attributs utilisés par la méthode Mi. P : nombre de paires de méthodes dont les ensembles Ii et Ij sont disjoints. Q : paires avec intersection non vide. LCOM = P - Q si P &gt; Q, sinon 0.</p><p>Exemple : M1 {a,b,c,d,e}, M2 {a,b,c}, M3 {x,y,z}. Seule la paire (M1,M2) partage : Q = 1, P = 2, LCOM = 1. Une classe cohésive regroupe des méthodes centrées sur une même responsabilité, ce qui améliore encapsulation et réutilisabilité.</p>" },
  { ch: 5, q: "Définir et interpréter l'indice de spécialisation SI.",
    a: "<p>SI = NORM × DIT / NOM. Il augmente avec les méthodes redéfinies (NORM) et la profondeur (DIT), diminue avec le nombre de méthodes propres (NOM).</p><ul><li>≈ 0 : classe générique, flexible.</li><li>≈ 0,5 à 1 : équilibre, bon niveau de réutilisation.</li><li>&gt; 1,5 : très spécialisée, risque de rigidité, refactorisation recommandée.</li></ul><p>Exemple : C3 hérite de C2 hérite de C1, redéfinit ses 3 méthodes : SI = 3 × 3 / 3 = 3.</p>" },
  { ch: 5, q: "Qu'est-ce que l'abstractivité, l'instabilité et la distance (Robert C. Martin) ?",
    a: "<ul><li>A = Nabstrait / Ntotal : proportion de classes abstraites et d'interfaces. 0 : concret, 1 : abstrait.</li><li>I = Ce / (Ca + Ce). Ca : classes extérieures qui dépendent du package. Ce : classes dont il dépend. I proche de 0 : stable. I proche de 1 : instable.</li><li>D = |A + I - 1| : distance à la séquence principale (A + I = 1). Proche de 0 : bonne conception.</li></ul><p>Interprétation de D moyen : moins de 0,3 très bonne architecture, 0,3 à 0,5 acceptable, plus de 0,5 déséquilibrée.</p>" },
  { ch: 5, q: "Interpréter les cas typiques de A, I et D.",
    a: "<ul><li>A = 0, I = 0,1, D = 0,9 : concret et stable, trop rigide.</li><li>A = 1, I = 0,8, D = 0,2 : abstrait et instable, bien conçu (il définit des interfaces que d'autres implémentent).</li><li>A = 0,5, I = 0,5, D = 0 : idéal, sur la séquence principale.</li></ul>" },
  { ch: 5, q: "Rappeler les principes SOLID.",
    a: "<ul><li>S, Single Responsibility : une classe, une seule responsabilité.</li><li>O, Open/Closed : ouverte à l'extension, fermée à la modification.</li><li>L, Liskov Substitution : les sous-classes remplacent leurs super-classes sans altérer le comportement.</li><li>I, Interface Segregation : plusieurs petites interfaces plutôt qu'une générale.</li><li>D, Dependency Inversion : dépendre d'abstractions, pas d'implémentations.</li></ul>" },
  { ch: 6, q: "Présenter SonarQube.",
    a: "<p>Solution web open source qui gère la qualité du code de façon centralisée (vue globale des projets). Plus de 25 langages. Intégration DevOps : outils CI (Jenkins, TravisCI, Azure DevOps), notifications succès ou échec, haute disponibilité. Sécurisé et basé sur RBAC.</p><p>7 axes : respect des standards, anomalies potentielles, complexité, duplications, architecture et design (code spaghetti), absence de tests unitaires, documentation et commentaires.</p>" },
  { ch: 6, q: "Qu'est-ce que le Quality Gate de SonarQube ?",
    a: "<p>Une porte qualité qui répond : puis-je livrer en production aujourd'hui ? Résultat PASSED ou FAILED, selon par exemple l'absence d'anomalies bloquantes, une couverture de code supérieure à 80 % et d'autres indicateurs de sécurité, fiabilité et maintenabilité.</p>" },
  { ch: 6, q: "Quelle différence entre complexité cyclomatique et complexité cognitive dans SonarQube ?",
    a: "<p>La cyclomatique (McCabe) compte les décisions, donc les chemins linéairement indépendants (if, else, case). La cognitive, inventée en 2016 par SonarSource, qualifie l'effort nécessaire pour comprendre un algorithme, sans fondement mathématique.</p>" },
  { ch: 6, q: "Décrire les étapes du TP SonarQube.",
    a: "<ol><li>Lancer StartSonar.bat, ouvrir http://localhost:9000/, créer le projet (nom, clé), générer un token, choisir Java et le système.</li><li>Préparer le projet : sources dans src/, compiler vers bin/, mettre le token dans sonar-project.properties.</li><li>Lancer sonar-scanner.bat.</li><li>Lire le dashboard : bugs, code smells, duplications, vulnérabilités.</li><li>Améliorer : supprimer commentaires inutiles et doublons, ajouter les getters, corriger getAvailableItems().</li><li>Relancer et comparer. Identifier les deux méthodes les plus complexes (cyclomatique et cognitive) et les découper.</li><li>Rédiger le rapport : problèmes, améliorations, résultats.</li></ol>" },
  { ch: 6, q: "Décrire le TP des métriques POO (CKJM).",
    a: "<ol><li>Compiler avec javac vers bin/ (cible JVM 8).</li><li>Lancer ckjm-1.8.jar sur les .class, rediriger vers metrics.txt (WMC, DIT, NOC, CBO, RFC, LCOM, Ca, NPM par classe).</li><li>Compléter le tableau des métriques et repérer les classes à WMC, CBO, RFC, LCOM élevés.</li><li>Analyse critique : classe la plus complexe, la plus cohérente, corrélation WMC et RFC, risque de faible réutilisabilité, package le plus stable (Ca élevé, Ce faible).</li><li>Refactoring : au moins 3 pistes, comparaison avant et après, compte-rendu de 1 à 2 pages.</li></ol>" },
  { ch: 1, q: "Comment faire le TD1 (autopsie d'un échec logiciel) ?",
    a: "<p>Choisir un cas (Mariner 1, Therac-25, Boeing 737 MAX, Heartbleed...). Rapport d'une page en PDF : (1) présentation du cas et domaine, (2) chaîne causale : erreur humaine, défaut, défaillance, (3) impacts financiers, humains, réputation, juridiques, (4) mesures SQA reliées aux phases du SDLC, (5) références. Un modèle complet est dans la page TD, TP et exercices.</p>" }
];
